import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '근태 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function isId(v: unknown): boolean {
  if (typeof v !== 'number' && typeof v !== 'string') return false;
  if (typeof v === 'string' && v.trim() === '') return false;
  const n = Number(v);
  return Number.isInteger(n) && n > 0;
}

function isDateText(v: unknown): boolean {
  return typeof v === 'string' && v.length === 10 && v[4] === '-' && v[7] === '-';
}

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

@Controller('api/v1')
export class FnSfr01703Controller {
  @Get('/employee-attendance-settings')
  async listEmployeeAttendanceSettings(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const hasEmployee = query['employeeId'] !== undefined && query['employeeId'] !== null && query['employeeId'] !== '';
    if (hasEmployee && !isId(query['employeeId'])) {
      throw invalid('임직원 값이 올바르지 않습니다.');
    }
    const employeeId = hasEmployee ? Number(query['employeeId']) : null;
    const pageRaw = Number(query['page'] ?? 0);
    const sizeRaw = Number(query['size'] ?? DEFAULT_SIZE);
    const page = Number.isInteger(pageRaw) && pageRaw > 0 ? pageRaw : 0;
    const size = Number.isInteger(sizeRaw) && sizeRaw > 0 ? Math.min(sizeRaw, MAX_SIZE) : DEFAULT_SIZE;
    return transaction(async (db) => {
      if (employeeId !== null) {
        const found = await db.query(
          'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
          { employeeId },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '조회할 임직원을 찾을 수 없습니다.');
        }
      }
      const counted = await db.query(
        'SELECT COUNT(*) AS "total" FROM employee_attendance_setting WHERE (CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint))',
        { employeeId },
      );
      const items = await db.query(
        'SELECT employee_attendance_setting_id AS "employeeAttendanceSettingId", employee_id AS "employeeId", attendance_item_id AS "attendanceItemId", apply_standard AS "applyStandard", to_char(apply_start_date, \'YYYY-MM-DD\') AS "applyStartDate", to_char(apply_end_date, \'YYYY-MM-DD\') AS "applyEndDate" FROM employee_attendance_setting WHERE (CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint)) ORDER BY employee_attendance_setting_id DESC LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)',
        { employeeId, size, offset: page * size },
      );
      return { items, page, size, total: Number(counted[0]['total']) };
    });
  }

  @Post('/employee-attendance-settings')
  @HttpCode(200)
  async createEmployeeAttendanceSetting(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    if (!isId(data['employeeId'])) throw invalid('임직원을 선택해 주세요.');
    if (!isId(data['attendanceItemId'])) throw invalid('근태항목을 선택해 주세요.');
    const standardGiven = data['applyStandard'] !== undefined && data['applyStandard'] !== null && data['applyStandard'] !== '';
    if (standardGiven && (typeof data['applyStandard'] !== 'string' || data['applyStandard'].length > 200)) {
      throw invalid('적용 근태 기준은 200자 이하로 입력해 주세요.');
    }
    const startGiven = data['applyStartDate'] !== undefined && data['applyStartDate'] !== null && data['applyStartDate'] !== '';
    if (startGiven && !isDateText(data['applyStartDate'])) {
      throw invalid('적용 시작일은 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const params = {
      employeeId: Number(data['employeeId']),
      attendanceItemId: Number(data['attendanceItemId']),
      applyStandard: standardGiven ? data['applyStandard'] : null,
      applyStartDate: startGiven ? data['applyStartDate'] : null,
    };
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId: params.employeeId },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '임직원을 찾을 수 없습니다.');
      }
      const items = await db.query(
        'SELECT use_yn AS "useYn", name FROM attendance_item WHERE attendance_item_id = CAST(:attendanceItemId AS bigint)',
        { attendanceItemId: params.attendanceItemId },
      );
      if (items.length === 0) throw invalid('근태항목을 찾을 수 없습니다.');
      // 가정: 미사용 근태항목은 임직원에게 적용할 수 없다 (확인 필요 표시 규칙, 최종 승인된 것으로 구현)
      if (items[0]['useYn'] !== '사용') {
        throw new ApiError(422, 'ATTENDANCE_ITEM_UNUSED', '미사용 근태항목은 적용할 수 없습니다.');
      }
      // 가정: 적용 시작일을 입력하지 않으면 당일로 한다
      const duplicated = await db.query(
        'SELECT 1 FROM employee_attendance_setting WHERE employee_id = CAST(:employeeId AS bigint) AND attendance_item_id = CAST(:attendanceItemId AS bigint) AND apply_start_date = COALESCE(CAST(:applyStartDate AS date), CAST(now() AS date))',
        params,
      );
      if (duplicated.length > 0) throw invalid('같은 근태항목·적용 시작일의 설정이 이미 있습니다.');
      const inserted = await db.query(
        'INSERT INTO employee_attendance_setting (employee_id, attendance_item_id, apply_start_date, apply_standard, created_at, updated_at) VALUES (CAST(:employeeId AS bigint), CAST(:attendanceItemId AS bigint), COALESCE(CAST(:applyStartDate AS date), CAST(now() AS date)), :applyStandard, now(), now()) RETURNING employee_attendance_setting_id AS "employeeAttendanceSettingId", to_char(apply_start_date, \'YYYY-MM-DD\') AS "startText"',
        params,
      );
      const newId = Number(inserted[0]['employeeAttendanceSettingId']);
      const content = '등록: 임직원 ' + params.employeeId + ', 근태항목 ' + items[0]['name'] + ', 적용 기준 ' + (params.applyStandard ?? '-') + ', 적용 시작일 ' + inserted[0]['startText'];
      await db.execute(
        'INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, created_at, updated_at) VALUES (CAST(:userId AS bigint), \'employee_attendance_setting\', CAST(:targetId AS bigint), \'설정 변경\', now(), :content, now(), now())',
        { userId: user.id, targetId: newId, content },
      );
      return { employeeAttendanceSettingId: newId };
    });
  }

  @Put('/employee-attendance-settings/:employeeAttendanceSettingId')
  async updateEmployeeAttendanceSetting(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const idText = req.params['employeeAttendanceSettingId'];
    if (!isId(idText)) throw invalid('설정 ID가 올바르지 않습니다.');
    const settingId = Number(idText);
    const data = checks.inputOf(req.body);
    if (!isId(data['attendanceItemId'])) throw invalid('근태항목을 선택해 주세요.');
    const standardGiven = data['applyStandard'] !== undefined && data['applyStandard'] !== null && data['applyStandard'] !== '';
    if (standardGiven && (typeof data['applyStandard'] !== 'string' || data['applyStandard'].length > 200)) {
      throw invalid('적용 근태 기준은 200자 이하로 입력해 주세요.');
    }
    const startGiven = data['applyStartDate'] !== undefined && data['applyStartDate'] !== null && data['applyStartDate'] !== '';
    if (startGiven && !isDateText(data['applyStartDate'])) {
      throw invalid('적용 시작일은 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const attendanceItemId = Number(data['attendanceItemId']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT s.employee_id AS "employeeId", s.attendance_item_id AS "attendanceItemId", s.apply_standard AS "applyStandard", to_char(s.apply_start_date, \'YYYY-MM-DD\') AS "applyStartDate" FROM employee_attendance_setting s WHERE s.employee_attendance_setting_id = CAST(:settingId AS bigint) FOR UPDATE',
        { settingId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_ATTENDANCE_SETTING_NOT_FOUND', '근태 적용 설정을 찾을 수 없습니다.');
      }
      const before = rows[0];
      const items = await db.query(
        'SELECT use_yn AS "useYn", name FROM attendance_item WHERE attendance_item_id = CAST(:attendanceItemId AS bigint)',
        { attendanceItemId },
      );
      if (items.length === 0) throw invalid('근태항목을 찾을 수 없습니다.');
      // 가정: 미사용 근태항목은 적용할 수 없다 (확인 필요 표시 규칙, 최종 승인된 것으로 구현). 항목을 바꿀 때만 검사한다
      if (Number(before['attendanceItemId']) !== attendanceItemId && items[0]['useYn'] !== '사용') {
        throw new ApiError(422, 'ATTENDANCE_ITEM_UNUSED', '미사용 근태항목은 적용할 수 없습니다.');
      }
      const params = {
        settingId,
        attendanceItemId,
        applyStandard: standardGiven ? data['applyStandard'] : before['applyStandard'],
        applyStartDate: startGiven ? data['applyStartDate'] : before['applyStartDate'],
      };
      const duplicated = await db.query(
        'SELECT 1 FROM employee_attendance_setting WHERE employee_id = CAST(:employeeId AS bigint) AND attendance_item_id = CAST(:attendanceItemId AS bigint) AND apply_start_date = CAST(:applyStartDate AS date) AND employee_attendance_setting_id <> CAST(:settingId AS bigint)',
        { ...params, employeeId: Number(before['employeeId']) },
      );
      if (duplicated.length > 0) throw invalid('같은 근태항목·적용 시작일의 설정이 이미 있습니다.');
      const endBefore = await db.query(
        'SELECT 1 FROM employee_attendance_setting WHERE employee_attendance_setting_id = CAST(:settingId AS bigint) AND apply_end_date < CAST(:applyStartDate AS date)',
        params,
      );
      if (endBefore.length > 0) throw invalid('적용 시작일은 적용 종료일보다 늦을 수 없습니다.');
      await db.execute(
        'UPDATE employee_attendance_setting SET attendance_item_id = CAST(:attendanceItemId AS bigint), apply_standard = :applyStandard, apply_start_date = CAST(:applyStartDate AS date), updated_at = now() WHERE employee_attendance_setting_id = CAST(:settingId AS bigint)',
        params,
      );
      const content = '변경 전: 근태항목 ' + before['attendanceItemId'] + ', 적용 기준 ' + (before['applyStandard'] ?? '-') + ', 적용 시작일 ' + before['applyStartDate'] + ' / 변경 후: 근태항목 ' + attendanceItemId + ', 적용 기준 ' + (params.applyStandard ?? '-') + ', 적용 시작일 ' + params.applyStartDate;
      await db.execute(
        'INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, created_at, updated_at) VALUES (CAST(:userId AS bigint), \'employee_attendance_setting\', CAST(:targetId AS bigint), \'설정 변경\', now(), :content, now(), now())',
        { userId: user.id, targetId: settingId, content },
      );
      return { employeeAttendanceSettingId: settingId };
    });
  }
}

