import { useState } from 'react';
import {
  call,
  useData,
  Band,
  DataTable,
  Pager,
  Filters,
  Field,
  Drawer,
  Form,
  TextInput,
  DateInput,
  DateText,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const PAGE_SIZE = 20;

export default function FnSfr01703Page({ role, notify }: PageProps) {
  const [draftEmployee, setDraftEmployee] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);

  const list = useData<Page>(
    () => call<Page>('GET', '/employee-attendance-settings', role, undefined, { employeeId, page, size: PAGE_SIZE }),
    [employeeId, page],
  );

  const [formEmployee, setFormEmployee] = useState<number | string>('');
  const [formItem, setFormItem] = useState<number | string>('');
  const [formStandard, setFormStandard] = useState('');
  const [formStart, setFormStart] = useState('');

  function openCreate() {
    setFormEmployee('');
    setFormItem('');
    setFormStandard('');
    setFormStart('');
    setCreating(true);
  }

  function openEdit(row: Row) {
    setFormItem(row['attendanceItemId'] as number);
    setFormStandard((row['applyStandard'] as string) ?? '');
    setFormStart((row['applyStartDate'] as string) ?? '');
    setEditing(row);
  }

  async function submitCreate() {
    if (formEmployee === '') throw new Error('임직원을 선택해 주세요.');
    if (formItem === '') throw new Error('근태항목을 선택해 주세요.');
    await call('POST', '/employee-attendance-settings', role, {
      employeeId: formEmployee,
      attendanceItemId: formItem,
      applyStandard: formStandard,
      applyStartDate: formStart,
    });
    notify('근태 적용 설정을 등록했습니다.');
    setCreating(false);
    setPage(0);
    list.reload();
  }

  async function submitEdit() {
    if (formItem === '') throw new Error('근태항목을 선택해 주세요.');
    await call('PUT', '/employee-attendance-settings/' + String(editing?.['employeeAttendanceSettingId']), role, {
      attendanceItemId: formItem,
      applyStandard: formStandard,
      applyStartDate: formStart,
    });
    notify('근태 적용 설정을 수정했습니다.');
    setEditing(null);
    list.reload();
  }

  const data = list.data;

  return (
    <div className="doc">
      <section className="box">
        <h2>임직원별 근태 적용 설정</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setEmployeeId(draftEmployee);
          }}
          onReset={() => {
            setDraftEmployee('');
            setPage(0);
            setEmployeeId('');
          }}
        >
          <Field label="임직원">
            <LookupSelect table="employee" role={role} value={draftEmployee} onChange={setDraftEmployee} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button onClick={openCreate}>설정 등록</button>
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'attendanceItemId', label: '근태항목', render: (r) => <RefName table="attendance_item" role={role} value={r['attendanceItemId']} /> },
            { key: 'applyStandard', label: '적용 근태 기준' },
            { key: 'applyStartDate', label: '적용 시작일', render: (r) => <DateText value={r['applyStartDate']} /> },
            { key: 'applyEndDate', label: '적용 종료일', render: (r) => <DateText value={r['applyEndDate']} /> },
          ]}
          rows={data?.items ?? []}
          onRowClick={openEdit}
          empty="아직 등록한 근태 적용 설정이 없습니다. 설정 등록 버튼으로 추가해 주세요."
        />
        <Pager page={data?.page ?? 0} size={data?.size ?? PAGE_SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>

      {creating ? (
        <Drawer title="근태 적용 설정 등록" onClose={() => setCreating(false)}>
          <Form onSubmit={submitCreate} submit="등록">
            <Field label="임직원" required>
              <LookupSelect table="employee" role={role} value={formEmployee} onChange={setFormEmployee} />
            </Field>
            <Field label="근태항목" required>
              <LookupSelect table="attendance_item" role={role} value={formItem} onChange={setFormItem} />
            </Field>
            <Field label="적용 근태 기준">
              <TextInput value={formStandard} onChange={setFormStandard} />
            </Field>
            <Field label="적용 시작일" hint="비워 두면 오늘부터 적용합니다.">
              <DateInput value={formStart} onChange={setFormStart} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {editing ? (
        <Drawer title="근태 적용 설정 수정" onClose={() => setEditing(null)}>
          <Form onSubmit={submitEdit} submit="수정" note="수정하면 변경 이력이 남습니다.">
            <Field label="임직원">
              <RefName table="employee" role={role} value={editing['employeeId']} />
            </Field>
            <Field label="근태항목" required>
              <LookupSelect table="attendance_item" role={role} value={formItem} onChange={setFormItem} />
            </Field>
            <Field label="적용 근태 기준">
              <TextInput value={formStandard} onChange={setFormStandard} />
            </Field>
            <Field label="적용 시작일">
              <DateInput value={formStart} onChange={setFormStart} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
